.rating-summary { display: flex; flex-direction: column; align-items: flex-start; gap: 8px; }
.rating-summary .t-h2 { margin-bottom: 12px; }
.rating-big { display: flex; align-items: baseline; gap: 6px; line-height: 1; }
.rating-big strong { font-size: 56px; font-weight: 800; }
.rating-big span { font-size: 20px; font-weight: 600; color: var(--muted); }
.rating-bars { display: grid; gap: 8px; width: 100%; margin-top: 12px; }
.rating-bars li { display: grid; grid-template-columns: 72px minmax(0, 1fr) 36px; align-items: center; gap: 10px; font-size: 13px; }
.rating-bars b { text-align: right; font-weight: 600; }
.rating-bars .bar i { background: var(--navy); }
.review-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }

/* ---------- FAQ teaser ---------- */
.faq-teaser { display: grid; grid-template-columns: 360px minmax(0, 1fr); gap: 56px; align-items: start; }
.faq-teaser-intro { display: flex; flex-direction: column; align-items: flex-start; gap: 12px; }
.faq-teaser-intro .eyebrow { margin-bottom: 0; }
.faq-teaser-intro p { margin-bottom: 8px; }
.faq-list-narrow { max-width: 860px; }

/* ---------- CTA band ---------- */
.cta-section { padding-top: 24px; }
.cta-band { position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 24px 48px; padding: 48px 56px; border-radius: 12px; background: var(--panel); overflow: hidden; }
.cta-band::after { content: ""; position: absolute; right: -60px; bottom: -120px; width: 320px; height: 320px; border-radius: 50%; border: 36px solid rgba(84, 163, 216, .14); pointer-events: none; }
.cta-copy p { margin-top: 10px; color: var(--muted); max-width: 560px; }
.cta-band .btn-row { position: relative; z-index: 1; }
.cta-trust { grid-column: 1 / -1; display: flex; flex-wrap: wrap; gap: 8px 28px; padding-top: 20px; border-top: 1px solid rgba(11, 37, 69, .12); font-size: 14px; font-weight: 500; }
.cta-trust li { display: inline-flex; align-items: center; gap: 8px; }

/* ---------- Page top / breadcrumb ---------- */
.page-top { padding: 24px 0 40px; background: var(--page); border-bottom: 1px solid var(--border); }
.page-top-slim { padding-bottom: 0; background: #fff; border-bottom: 0; }
.breadcrumb ol { display: flex; flex-wrap: wrap; align-items: center; gap: 4px; font-size: 14px; color: var(--muted); margin-bottom: 20px; }
.breadcrumb li { display: inline-flex; align-items: center; gap: 4px; }
.breadcrumb li + li::before { content: ""; width: 6px; height: 6px; margin: 0 6px; border-right: 1.5px solid var(--control); border-top: 1.5px solid var(--control); transform: rotate(45deg); }
.breadcrumb a { text-decoration: underline; text-underline-offset: 3px; text-decoration-color: var(--control); color: var(--navy); }
.breadcrumb a:hover { text-decoration-color: var(--navy); }
.breadcrumb [aria-current] { color: var(--navy); font-weight: 600; }
.page-head { display: flex; justify-content: space-between; align-items: flex-end; gap: 40px; }
.page-head-copy .lead { margin-top: 12px; }
.page-head-usps { display: grid; gap: 8px; font-size: 14px; font-weight: 500; flex: none; }
.page-head-usps li { display: flex; align-items: center; gap: 8px; }
.chip-row { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 28px; }

/* ---------- Shop ---------- */
.shop-section { padding: 32px 0 var(--section); }
.shop { position: relative; display: grid; grid-template-columns: 264px minmax(0, 1fr); gap: 32px; align-items: start; }
.filters { position: sticky; top: 104px; display: flex; flex-direction: column; gap: 4px; }
.filters-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 4px; }
.filters-close { display: none; }
.filter-group { padding: 16px 0; border-top: 1px solid var(--border); }
.filter-title { float: left; width: 100%; font-size: 15px; font-weight: 700; margin-bottom: 8px; }
.filter-title + * { clear: both; }
.check { display: flex; align-items: center; gap: 12px; min-height: 40px; cursor: pointer; font-size: 15px; position: relative; }
.check input { position: absolute; opacity: 0; width: 22px; height: 22px; margin: 0; cursor: pointer; }
.check-box { display: grid; place-items: center; width: 22px; height: 22px; border-radius: var(--r-sm); border: 1.5px solid var(--control); background: #fff; color: #fff; flex: none; transition: background-color .15s, border-color .15s; }
.check-box .ic { width: 14px; height: 14px; stroke-width: 3; opacity: 0; }
.check input:checked + .check-box { background: var(--navy); border-color: var(--navy); }
.check input:checked + .check-box .ic { opacity: 1; }
.check input:focus-visible + .check-box { outline: 2px solid var(--navy); outline-offset: 2px; }
.check:hover .check-box { border-color: var(--navy); }
.check-radio .check-box { border-radius: 50%; }
.check-radio input:checked + .check-box { background: #fff; box-shadow: inset 0 0 0 5px var(--navy); }
.check-label { flex: 1; line-height: 1.4; }
.check-count { font-size: 13px; color: var(--muted); }
.filters-foot { display: grid; gap: 8px; padding-top: 16px; border-top: 1px solid var(--border); }
.filters-apply { display: none; }
.help-card { display: flex; flex-direction: column; align-items: flex-start; gap: 8px; margin-top: 20px; padding: 20px; background: var(--page); border-radius: var(--r-lg); }
.help-title { font-size: 16px; font-weight: 700; line-height: 1.35; }
.shop-main { min-width: 0; }
.toolbar { display: flex; align-items: center; gap: 12px; margin-bottom: 16px; }
.search { position: relative; flex: 1; max-width: 460px; }
.search > .ic { position: absolute; left: 14px; top: 50%; transform: translateY(-50%); color: var(--navy); pointer-events: none; }
.search .input { padding-left: 44px; }
.search-lg { max-width: 640px; margin-top: 24px; }
.search-lg .input { height: 56px; font-size: 17px; }
.input { width: 100%; height: 48px; padding: 0 14px; border: 1.5px solid var(--control); border-radius: var(--r-md); background: #fff; font-size: 16px; color: var(--navy); transition: border-color .15s; }
.input::placeholder { color: #7b8794; }
.input:hover { border-color: var(--navy); }
.input:focus-visible { outline: 2px solid var(--navy); outline-offset: 2px; border-color: var(--navy); }
.textarea { height: auto; padding: 12px 14px; resize: vertical; line-height: 1.5; }
.filters-open { display: none; }
.sort { display: flex; align-items: center; gap: 10px; margin-left: auto; }
.sort-label { font-size: 14px; font-weight: 600; white-space: nowrap; }
.select { position: relative; display: inline-flex; }
.select select { appearance: none; -webkit-appearance: none; height: 48px; padding: 0 40px 0 14px; border: 1.5px solid var(--control); border-radius: var(--r-md); background: #fff; font-size: 15px; font-weight: 600; color: var(--navy); cursor: pointer; }
.select select:hover { border-color: var(--navy); }
.select > .ic { position: absolute; right: 14px; top: 50%; transform: translateY(-50%); pointer-events: none; }
.select-block, .select-block select { width: 100%; }
.select-block select { font-weight: 500; font-size: 16px; }
.results-bar { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 16px; min-height: 40px; margin-bottom: 16px; }
.result-count { font-size: 15px; color: var(--muted); }
.result-count strong { color: var(--navy); }
.active-filters { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.empty { display: flex; flex-direction: column; align-items: center; gap: 12px; padding: 56px 24px; text-align: center; background: var(--page); border-radius: var(--r-lg); }
.empty-ic { display: grid; place-items: center; width: 64px; height: 64px; border-radius: 50%; background: #fff; border: 1px solid var(--border); }
.empty-lg { padding: 80px 24px; }
.empty-lg .btn-row { margin-top: 12px; }
.guide-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; }

